WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY delivered_date DESC, id) AS latest_rank FROM shipments) x WHERE latest_rank = 1) SELECT carrier, ROUND(AVG(cost), 2) AS avg_cost, COUNT(*) AS row_count, SUM(CASE WHEN carrier = 'Flash' THEN cost ELSE 0 END) AS flash_cost FROM ranked GROUP BY 1 HAVING COUNT(*) < 1000 ORDER BY flash_cost DESC NULLS FIRST;
